args.query:
\dn
\dt api.*
\dv api.*
\df api.*
select table_schema,table_name,column_name,data_type,is_nullable,column_default from information_schema.columns where table_schema not in ('pg_catalog','information_schema') order by 1,2,ordinal_position;
select * from api.app_user;
select rolname,rolsuper,rolbypassrls from pg_roles where rolname !~ '^pg_';
select n.nspname,c.relname,c.relkind,c.relrowsecurity,pg_get_userbyid(c.relowner) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('api','public') and c.relkind in ('r','v','m');
select tgname,tgrelid::regclass from pg_trigger where not tgisinternal;

select * from api.status order by ord;
select * from api.company;
select id,number,company_id,status_id,amount,expert,verdict from api.application order by id;
select conname,contype,pg_get_constraintdef(oid) from pg_constraint where connamespace='api'::regnamespace;
select grantee,table_name,privilege_type from information_schema.role_table_grants where table_schema='api' and grantee not in ('postgres');
show request.jwt.claims;

select * from api.status order by ord;
select * from api.company;
select id,number,company_id,status_id,amount,expert,verdict from api.application order by id;
select conname,contype,pg_get_constraintdef(oid) from pg_constraint where connamespace='api'::regnamespace;
select grantee,table_name,privilege_type from information_schema.role_table_grants where table_schema='api' and grantee not in ('postgres');

begin;
-- helpers
create or replace function api.cur_login() returns text language sql stable as $$
  select coalesce(nullif(nullif(current_setting('request.jwt.claims',true),'')::json->>'login',''), current_user::text) $$;
create or replace function api.is_ai() returns boolean language sql stable as $$
  select coalesce(nullif(current_setting('request.headers',true),'')::json->>'x-client','')='ai' $$;
create or replace function api.cur_company() returns int language sql stable security definer set search_path=api,pg_temp as $$
  select company_id from api.app_user where login=api.cur_login() $$;

-- R6
alter table api.application alter column amount set not null;
alter table api.application alter column status_id set default 20000;

-- audit & confirmation
create table api.audit(id bigserial primary key, ts timestamptz not null default now(), actor text not null, via text not null check (via in ('ai','human')), op text not null, app_id int);
create table api.confirmation(id bigserial primary key, actor text not null default api.cur_login(), op text not null check (op in ('delete','bulk_update')), app_id int, used boolean not null default false, created_at timestamptz not null default now());

create or replace function api.app_guard() returns trigger language plpgsql security definer set search_path=api,pg_temp as $$
declare o int; n int; lim numeric;
begin
  select ord into n from api.status where id=new.status_id;
  if tg_op='INSERT' then
    if n is distinct from 1 then raise exception 'новая заявка создаётся в статусе Черновик' using errcode='23514'; end if;
  elsif new.status_id is distinct from old.status_id then
    select ord into o from api.status where id=old.status_id;
    if not ((o=1 and n=2) or (o=2 and n=3) or (o=3 and n in (4,5))) then
      raise exception 'недопустимый переход статуса' using errcode='23514'; end if;
  end if;
  if n in (4,5) and coalesce(btrim(new.verdict),'')='' then
    raise exception 'нужно заключение эксперта' using errcode='23514'; end if;
  if n=4 then
    select funding_limit into lim from api.company where id=new.company_id;
    if lim is null or new.amount>lim then raise exception 'сумма превышает лимит компании' using errcode='23514'; end if;
  end if;
  return new;
end $$;
create trigger app_guard before insert or update on api.application for each row execute function api.app_guard();

create or replace function api.consume(p_op text, p_app int) returns boolean language plpgsql security definer set search_path=api,pg_temp as $$
declare c bigint;
begin
  select id into c from api.confirmation where actor=api.cur_login() and op=p_op and app_id is not distinct from p_app and not used and created_at>now()-interval '15 minutes' order by id limit 1 for update;
  if c is null then return false; end if;
  update api.confirmation set used=true where id=c; return true;
end $$;

create or replace function api.ai_del_guard() returns trigger language plpgsql as $$
begin
  if api.is_ai() and not api.consume('delete', old.id) then
    raise exception 'удаление агентом требует подтверждения человеком (api.confirmation op=delete, app_id=%)', old.id using errcode='42501'; end if;
  return old;
end $$;
create trigger ai_del_guard before delete on api.application for each row execute function api.ai_del_guard();

create or replace function api.ai_bulk_guard() returns trigger language plpgsql as $$
declare k int;
begin
  select count(*) into k from nt;
  if k>1 and api.is_ai() and not api.consume('bulk_update', null) then
    raise exception 'массовая правка агентом требует подтверждения человеком (api.confirmation op=bulk_update)' using errcode='42501'; end if;
  return null;
end $$;
create trigger ai_bulk_guard after update on api.application referencing new table as nt for each statement execute function api.ai_bulk_guard();

create or replace function api.audit_fn() returns trigger language plpgsql security definer set search_path=api,pg_temp as $$
begin
  insert into api.audit(actor,via,op,app_id) values (api.cur_login(), case when api.is_ai() then 'ai' else 'human' end, lower(tg_op), coalesce(case when tg_op='DELETE' then old.id else new.id end,0));
  return null;
end $$;
create trigger audit_aiud after insert or update or delete on api.application for each row execute function api.audit_fn();

-- privileges
revoke all on all tables in schema api from public, anon, expert, applicant;
revoke truncate on api.application from fund_admin;
grant usage on schema api to fund_admin, expert, applicant;
grant select on api.status to expert, applicant;
grant select on api.company to expert, applicant;
grant select on api.audit to fund_admin;
grant select, insert(op,app_id), update(used) on api.confirmation to fund_admin; 
grant select, insert(op,app_id) on api.confirmation to expert, applicant;
grant usage on all sequences in schema api to fund_admin, expert, applicant;
grant select, insert, update, delete on api.confirmation to fund_admin;
grant select(id,number,company_id,status_id,amount,revenue,description,verdict) on api.application to applicant;
grant insert(number,company_id,status_id,amount,revenue,description) on api.application to applicant;
grant update(number,company_id,status_id,amount,revenue,description) on api.application to applicant;
grant delete on api.application to applicant;
grant select on api.application to expert;
grant update(status_id,expert,verdict) on api.application to expert;
grant execute on all functions in schema api to fund_admin, expert, applicant;

-- RLS
alter table api.application enable row level security;
alter table api.company enable row level security;
alter table api.confirmation enable row level security;
create policy adm on api.application for all to fund_admin using (true) with check (true);
create policy adm on api.company for all to fund_admin using (true) with check (true);
create policy adm on api.confirmation for all to fund_admin using (true) with check (true);
create policy ap_sel on api.application for select to applicant using (company_id=api.cur_company());
create policy ap_ins on api.application for insert to applicant with check (company_id=api.cur_company() and status_id=20000);
create policy ap_upd on api.application for update to applicant using (company_id=api.cur_company() and status_id in (20000,20001)) with check (company_id=api.cur_company() and status_id in (20000,20001));
create policy ap_del on api.application for delete to applicant using (company_id=api.cur_company() and status_id=20000);
create policy ex_sel on api.application for select to expert using (status_id<>20000);
create policy ex_upd on api.application for update to expert using (status_id in (20001,20002)) with check (status_id<>20000);
create policy co_ap on api.company for select to applicant using (id=api.cur_company());
create policy co_ex on api.company for select to expert using (true);
create policy cf_ins on api.confirmation for insert to expert, applicant with check (not api.is_ai() and actor=api.cur_login());
create policy cf_sel on api.confirmation for select to expert, applicant using (actor=api.cur_login());
commit;

drop policy adm on api.confirmation;
create policy adm_sel on api.confirmation for select to fund_admin using (true);
create policy adm_ins on api.confirmation for insert to fund_admin with check (not api.is_ai() and actor=api.cur_login());
revoke update, delete on api.confirmation from fund_admin;

set session_replication_role=replica;
update api.application set status_id=20002, verdict=null where id=20111;
update api.application set description=null where id in (20086,20092,20080,20099);
delete from api.audit; delete from api.confirmation;
select id,number,status_id,amount,description,verdict from api.application order by id;

set session_replication_role=replica;
update api.application set description='Проект '||right(number,1)||': модернизация производства' where id in (20080,20086,20092,20099);
select number,description from api.application order by id limit 4;
